 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # For each row, recognize zero gaps between matching colored cells.
    # Such a gap is the crossing point of a horizontal bar and vertical ray.
    crossing_color = {}
    for r, row in enumerate(grid):
        for c in range(1, w - 1):
            if row[c] == 0 and row[c - 1] != 0 and row[c - 1] == row[c + 1]:
                crossing_color[(r, c)] = row[c - 1]

    # Each vertical ray is a colored run touching the bottom. Extend it
    # upward from each horizontal crossing, using the color of that bar.
    for c in range(w):
        if grid[h - 1][c] == 0:
            continue
        # Only the vertical object connected to the bottom is a source ray.
        if not any(grid[r][c] != 0 for r in range(h)):
            continue
        crossings = sorted(r for (r, col) in crossing_color if col == c and r < h - 1)
        if not crossings:
            continue
        for i, r in enumerate(crossings):
            color = crossing_color[(r, c)]
            upper = crossings[i - 1] if i > 0 else -1
            for rr in range(upper + 1, r + 1):
                if out[rr][c] == 0:
                    out[rr][c] = color
    return out
