 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    beams = {}

    # Identify horizontal bars: a row with multiple same-colored cells and
    # at least one zero gap between its endpoints.
    for r, row in enumerate(grid):
        cols = [c for c, v in enumerate(row) if v]
        if len(cols) >= 2 and all(row[c] == row[cols[0]] for c in cols):
            if any(row[c] == 0 for c in range(cols[0], cols[-1] + 1)):
                beams[r] = (row[cols[0]], cols[0], cols[-1])
                for c in range(cols[0], cols[-1] + 1):
                    if out[r][c] == 0:
                        out[r][c] = row[cols[0]]

    # Extend each bottom-anchored vertical ray upward. At every bar crossing,
    # the bar's color fills its gap and colors the vertical segment above it;
    # the original ray color remains below the lowest crossing.
    for c in range(w):
        if grid[h - 1][c] == 0:
            continue
        base_color = grid[h - 1][c]
        crossings = sorted(
            (r for r, (_, left, right) in beams.items()
             if left <= c <= right and grid[r][c] == 0),
            reverse=True,
        )
        if not crossings:
            continue
        lowest = crossings[0]
        for r in range(lowest + 1, h):
            if out[r][c] == 0:
                out[r][c] = base_color
        for i, r in enumerate(crossings):
            color = beams[r][0]
            upper = crossings[i + 1] if i + 1 < len(crossings) else -1
            for rr in range(upper + 1, r + 1):
                out[rr][c] = color
    return out
